#!/usr/bin/env python3
"""Construct the universal rank-one envelope of the omega-zero rank-26 object."""
import json
from pathlib import Path
P=Path(__file__).resolve();ROOT=P.parents[3];R=ROOT/'research';B=R/'benincasa'/'results'
obs=json.loads((R/'voevodsky'/'results'/'cosmology_rank26_relative_pair_obstruction.json').read_text());assert 'im(omega_R)={0}' in obs['rank26_image'];assert obs['demand'].endswith('omega=1.')
rank=26;omega=[0]*rank+[1];kernel_basis=[[1 if i==j else 0 for i in range(rank+1)] for j in range(rank)];assert all(sum(a*b for a,b in zip(omega,v))==0 for v in kernel_basis);unit=[0]*rank+[1];assert sum(a*b for a,b in zip(omega,unit))==1
out={'schema':'marici.benincasa.cosmology-rank26-omega-minimal-extension.v1','construction':{'R_rank':26,'E':'R direct_sum Z*h','E_rank':27,'omega_E':'omega_E(r+n*h)=n','kernel_omega_E':'R','quotient_E_over_R':'Z','omega_h':1},'verified':{'rank_increment':1,'rank26_embeds_as_kernel':True,'unit_omega_exists':True,'smaller_free_extension_possible':False},'universal_property':'Any free relative-pair extension containing R and a primitive omega-one class receives a map from E after choosing such a class.','noncanonicity':'Every h+r with r in R also has omega=1; the omega-one lifts form an R-torsor, so omega alone does not choose the horn lift.','ordered_base_change':'Maps preserving R and omega preserve the kernel/quotient sequence; orientation reversal sends h and omega to their negatives without removing the unit quotient.','horn_boundary_status':'realized only if h is separately identified with the geometric horn; adjoining h is a formal minimal envelope, not a source derivation of that identification','decision':'The minimal free envelope is rank 27 with canonical omega-zero subobject R and quotient Z. It localizes the missing datum to a choice of omega-one lift, but does not canonically compare rank26 to the horn.','passed':True};(B/'cosmology_rank26_omega_minimal_extension.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
